import {lesPaul} from '../../wiring-kits/kit-data.mjs';
import {kitBindings} from '../kit-bindings.mjs';
import {parseGBP} from '../data.mjs';
import {aggregateRequirements} from '../assemblies.mjs';
export const draftKey='apparition.admin.wiring-kit-master.v1';
export const roles={bridgePot:{label:'Bridge Potentiometer',category:'potentiometers',quantity:2},bridgeCap:{label:'Bridge Tone Capacitor',category:'capacitors',quantity:1},bridgeBleed:{label:'Bridge Treble Bleed',category:'treble-bleeds',quantity:1},neckPot:{label:'Neck Potentiometer',category:'potentiometers',quantity:2},neckCap:{label:'Neck Tone Capacitor',category:'capacitors',quantity:1},neckBleed:{label:'Neck Treble Bleed',category:'treble-bleeds',quantity:1},jack:{label:'Output Jack',category:'jacks',quantity:1},toggle:{label:'Toggle Switch',category:'switches',quantity:1},cloth:{label:'Cloth Wire',category:'other',quantity:.25,unit:'m',consumable:true},braided:{label:'Braided Wire',category:'other',quantity:.25,unit:'m',consumable:true},solder:{label:'Solder',category:'other',quantity:1,consumable:true},heatShrink:{label:'Heat Shrink',category:'other',quantity:.25,unit:'m',consumable:true}};
export const eligible=(item,role)=>item.active&&item.inKits&&item.category===roles[role].category;
export function defaultDraft(){return {reference:'AI-10001',channel:'DIRECT',basePrice:(lesPaul.basePrice/100).toFixed(2),packaging:'0.00',labourRate:'0.00',labourMinutes:'0',feePercent:'0',feeFixed:'0.00',rows:Object.entries(roles).map(([role,meta])=>({role,include:false,componentId:'',quantity:String(meta.quantity),charge:!meta.consumable}))};}
export function createDraftStore(storage){return {load(){let raw;try{raw=storage.getItem(draftKey);}catch{throw new Error('Browser storage is unavailable.');}if(raw===null)return defaultDraft();try{const data=JSON.parse(raw);if(data.version!==1||!data.draft||!Array.isArray(data.draft.rows)||data.draft.rows.length!==Object.keys(roles).length||new Set(data.draft.rows.map(r=>r.role)).size!==Object.keys(roles).length||data.draft.rows.some(r=>!roles[r.role]))throw new Error();return data.draft;}catch{throw new Error('Saved Master draft could not be read. It has not been reset.');}},save(draft){try{storage.setItem(draftKey,JSON.stringify({version:1,draft}));}catch{throw new Error('Draft could not be saved. Browser storage may be full or disabled.');}}};}
export function unitKitPrice(item){const binding=kitBindings[item.id],quantity=binding?.group==='shaft'?4:binding?.group==='bleed'?2:binding?1:item.kitPriceQuantity??1;return {quantity,price:Number.isSafeInteger(item.kitPrice)&&item.kitPrice>=0?item.kitPrice/quantity:null,savedPrice:item.kitPrice??null};}
const sum=values=>values.some(v=>v===null)?null:values.reduce((a,b)=>a+b,0);
const amount=(value,label)=>{const result=parseGBP(value);if(result===null)throw new Error('Enter '+label+'.');return result;};
const number=(value,label,max=1000000)=>{if(String(value??'').trim()===''||!Number.isFinite(Number(value))||Number(value)<0||Number(value)>max)throw new Error('Enter a valid '+label+'.');return Number(value);};
export function deriveKitType(lines){const counts={pots:0,pushPull:0,caps:0,bleeds:0,jacks:0,switches:0};for(const line of lines){const p=line.component;if(!p)continue;const key=p.category==='potentiometers'?/push[\s/\-]*pull/i.test(p.specs?.Type||'')?'pushPull':'pots':({'capacitors':'caps','treble-bleeds':'bleeds','jacks':'jacks','switches':'switches'}[p.category]);if(key)counts[key]+=line.quantity;}return Object.entries({pots:'Pots',pushPull:'Push/Pull',caps:'Tone Caps',bleeds:'Treble Bleeds',jacks:'Output Jacks',switches:'Switches'}).filter(([k])=>counts[k]).map(([k,label])=>counts[k]+' '+label).join(' + ')||'No kit components selected';}
export function calculateMaster(draft,inventory){
 const warnings=[],lines=[];if(!['DIRECT','WEBSITE','EBAY','OTHER'].includes(draft.channel))throw new Error('Choose a sales channel.');
 for(const row of draft.rows){if(!row.include)continue;const meta=roles[row.role];if(!meta)throw new Error('Unknown component role.');const quantity=number(row.quantity,meta.label+' quantity');if(quantity<=0||(!meta.consumable&&!Number.isInteger(quantity)))throw new Error(meta.label+' requires '+(meta.consumable?'a positive quantity.':'a positive whole-number quantity.'));
  const component=inventory.find(p=>p.id===row.componentId),unit=component?.stockUnit||'item',valid=component&&eligible(component,row.role)&&(!meta.unit||unit===meta.unit);
  if(!component)warnings.push(meta.label+': select an existing component.');else if(!eligible(component,row.role))warnings.push(meta.label+': selected component is inactive or not eligible for this role.');else if(meta.unit&&unit!==meta.unit)warnings.push(meta.label+': set the central stock unit to metres and confirm its quantity and cost basis.');
  const pricing=component?unitKitPrice(component):{price:null,quantity:1,savedPrice:null},unitCost=Number.isSafeInteger(component?.internalUnitCost)&&component.internalUnitCost>=0?component.internalUnitCost:null;
  const lineCost=valid&&unitCost!==null?Math.round(quantity*unitCost):null,lineAddon=!row.charge?0:valid&&pricing.price!==null?Math.round(quantity*pricing.price):null;
  if(component&&unitCost===null)warnings.push(meta.label+': internal unit cost is not set.');if(component&&row.charge&&pricing.price===null)warnings.push(meta.label+': kit add-on price is not set.');
  lines.push({role:row.role,label:meta.label,componentId:row.componentId,component,sku:component?.sku??'',quantity,unit,internalUnitCost:unitCost,unitCustomerPrice:row.charge?pricing.price:0,kitPriceBasis:pricing.quantity,savedKitPrice:pricing.savedPrice,lineInternalCost:lineCost,lineCustomerAddon:lineAddon,charge:!!row.charge});
 }
 const {required,warnings:stockErrors}=aggregateRequirements(lines.map(l=>({componentId:l.componentId,quantity:l.quantity})),{fractional:true});warnings.push(...stockErrors);
 const stock=[...required].map(([id,quantity])=>{const item=inventory.find(p=>p.id===id);if(!item||!Number.isSafeInteger(item.stock)||item.stock<0){warnings.push('Stock cannot be checked for '+id);return {id,name:item?.name||id,required:quantity,available:null,after:null,shortfall:null,unit:item?.stockUnit||'item'};}const after=Math.round((item.stock-quantity)*1e6)/1e6;if(after<0)warnings.push(item.name+': insufficient stock ('+(-after)+' '+(item.stockUnit||'item')+' short).');return {id,name:item.name,required:quantity,available:item.stock,after,shortfall:Math.max(0,-after),unit:item.stockUnit||'item'};});
 const base=amount(draft.basePrice,'base kit price'),packaging=amount(draft.packaging,'packaging cost'),labourRate=amount(draft.labourRate,'labour rate'),minutes=number(draft.labourMinutes,'labour time in minutes'),labourCost=Math.round(labourRate*minutes/60),partsCost=sum(lines.map(l=>l.lineInternalCost)),customerAddons=sum(lines.map(l=>l.lineCustomerAddon)),salePrice=customerAddons===null?null:base+customerAddons;
 const feePercent=draft.channel==='EBAY'?number(draft.feePercent,'percentage fee',100):0,fixedFee=draft.channel==='EBAY'?amount(draft.feeFixed,'fixed fee'):0,marketplaceFee=salePrice===null?null:Math.round(salePrice*feePercent/100)+fixedFee;
 const grossProfit=[salePrice,partsCost,marketplaceFee].includes(null)?null:salePrice-partsCost-packaging-marketplaceFee,netProfit=grossProfit===null?null:grossProfit-labourCost;
 if([base,packaging,labourRate,labourCost,partsCost,customerAddons,salePrice,marketplaceFee,grossProfit,netProfit].some(v=>v!==null&&!Number.isSafeInteger(v)))throw new Error('These amounts exceed the supported calculation range.');
 return {schemaVersion:1,reference:draft.reference,channel:draft.channel,kitType:deriveKitType(lines),lines,stock,warnings:[...new Set(warnings)],costing:{base,partsCost,customerAddons,salePrice,packaging,feePercent,fixedFee,marketplaceFee,labourRate,minutes,labourCost,grossProfit,netProfit,grossMargin:grossProfit===null||!salePrice?null:grossProfit/salePrice*100,netMargin:netProfit===null||!salePrice?null:netProfit/salePrice*100}};
}
